package io.cascadeshield.sim;

import com.fasterxml.jackson.databind.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.util.*;
import static io.cascadeshield.sim.Models.*;
import static io.cascadeshield.sim.OpsModels.*;
import static io.cascadeshield.sim.AiModels.*;

/** Read-only fallback orchestration. Counterfactuals are estimates on copies, not experimental outcomes. */
public final class AiFallbackPipeline implements AiArchitecture.PredictionProvider,AiArchitecture.GraphRiskProvider,
        AiArchitecture.CandidateActionGenerator,AiArchitecture.CounterfactualEvaluator,AiArchitecture.ConstraintValidator,
        AiArchitecture.ActionOptimizer,AiArchitecture.DecisionExplainer {
    public static final Source SOURCE=new Source("RULE_BASED_FALLBACK","1.0","SIMULATED_PREDICTION",false,
        "Known incident schedule and configured simulated resources; uncalibrated scores, no learned model or optimal joint scheduling guarantee.");
    private final RoadGraph graph;private final ObjectMapper mapper;
    private final RuleBasedPredictionService prediction;private final RuleBasedPreventionService prevention;
    private final GraphSnapshotExporter exporter;private final OperationalRuntime operations;
    public AiFallbackPipeline(RoadGraph graph,ObjectMapper mapper){this.graph=graph;this.mapper=mapper;
        prediction=new RuleBasedPredictionService(graph);prevention=new RuleBasedPreventionService(graph,prediction);
        exporter=new GraphSnapshotExporter(graph,mapper);operations=new OperationalRuntime(graph,mapper);}
    public String fingerprint(State state) {
        try {
            ObjectMapper ordered=mapper.copy().configure(SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS,true);
            // Materializing a sorted JSON tree also normalizes object field order, independent of DTO declaration order.
            String json=ordered.writeValueAsString(sortTree(ordered.valueToTree(state)));
            return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(json.getBytes(StandardCharsets.UTF_8)));
        }catch(Exception exception){throw new IllegalStateException("Cannot fingerprint simulation state",exception);}
    }
    private JsonNode sortTree(JsonNode node){if(node.isObject()){var result=mapper.createObjectNode();List<String> keys=new ArrayList<>();node.fieldNames().forEachRemaining(keys::add);Collections.sort(keys);for(String key:keys)result.set(key,sortTree(node.get(key)));return result;}if(node.isArray()){var result=mapper.createArrayNode();node.forEach(value->result.add(sortTree(value)));return result;}return node;}
    private State copy(State state){return mapper.convertValue(state,State.class);}
    private Context context(State state){return new Context(API_VERSION,state.networkId,state.runId,state.scenarioId,state.randomSeed,state.clockSec,fingerprint(state));}
    private Truck truck(State state,String id){return state.trucks.stream().filter(t->Objects.equals(t.id,id)).findFirst().orElseThrow(()->ApiException.invalid("Unknown truck "+id));}
    private void updateEstimates(State state){for(Truck t:state.trucks){PredictionService.Estimate estimate=prediction.estimate(state,t);t.etaSec=estimate.arrivalSec();t.remainingDistanceM=estimate.remainingDistanceM();t.affectedIncidentIds=new ArrayList<>(estimate.incidentIds());}state.trucks.stream().sorted(Comparator.comparingDouble((Truck t)->t.departureSec).thenComparing(t->t.id)).forEach(t->{t.etaSec=operations.adjustEta(state,t,t.etaSec);t.risk=prediction.risk(t,t.etaSec,prediction.baseRemaining(t),state.clockSec);});}
    private void updateGraph(State state){operations.refresh(state,(time,type,message,truck,details)->{},false);state.operations.graph=new OperationalDependencyGraph().build(state);state.operations.cascade=new GraphRiskBaseline().predict(state,state.operations.graph);}
    public PredictionBatch predict(State input){State state=copy(input);updateEstimates(state);List<TruckPrediction> trucks=state.trucks.stream().sorted(Comparator.comparing(t->t.id)).map(t->new TruckPrediction(t.id,t.etaKnown?t.etaSec:null,t.etaSec,t.remainingDistanceM,t.risk.score(),List.copyOf(t.affectedIncidentIds),SOURCE)).toList();return new PredictionBatch(context(input),trucks,graphRisk(state),OperationalRuntime.forecast(state,Map.of()),SOURCE);}
    public CascadeView graphRisk(State input){State state=copy(input);updateEstimates(state);updateGraph(state);return state.operations.cascade;}
    public CandidateBatch candidates(State input,String truckId){State state=copy(input);updateEstimates(state);Truck t=truck(state,truckId);Recommendation recommendation=prevention.recommend(state,t);String signature=fingerprint(input);List<CandidateAction> actions=new ArrayList<>();if(recommendation!=null){for(Option option:recommendation.options())if(option.feasible()){String id=UUID.nameUUIDFromBytes((signature+":"+truckId+":"+option.action()).getBytes(StandardCharsets.UTF_8)).toString();actions.add(new CandidateAction(id,truckId,option.action(),recommendation.id(),signature,SOURCE));}}return new CandidateBatch(context(input),truckId,List.copyOf(actions),SOURCE);}
    private CandidateAction checkedCandidate(State input,CandidateAction requested){if(requested==null||requested.truckId()==null||requested.action()==null)throw ApiException.invalid("A typed candidate action is required.");if(!Objects.equals(requested.stateFingerprint(),fingerprint(input)))throw ApiException.conflict("The candidate state is stale; refresh prediction and request operator approval again.");return candidates(input,requested.truckId()).candidates().stream().filter(c->c.equals(requested)&&c.source().equals(requested.source())).findFirst().orElseThrow(()->ApiException.invalid("Candidate action or its source/version is not available under the current route and incident state."));}
    private record Trial(State state,double beforeArrival,double beforeRisk,boolean beforeKnown,double remaining) {}
    private Trial trial(State input,CandidateAction requested){CandidateAction action=checkedCandidate(input,requested);State state=copy(input);updateEstimates(state);Truck t=truck(state,action.truckId());double before=t.etaSec,beforeRisk=t.risk.score();boolean beforeKnown=t.etaKnown;if("WAIT".equals(action.action()))t.waitUntilSec=prevention.waitUntil(state,t);else if("CONTINUE".equals(action.action()))t.waitUntilSec=0;else if("REROUTE".equals(action.action())){RuleBasedPreventionService.ReroutePlan plan=prevention.reroute(state,t);t.route=graph.describe(plan.ids(),new Point(t.position.get(0),t.position.get(1)),t.destination,t.maxSpeedKph);t.edgeIndex=0;t.offsetM=plan.offsetM();t.waitUntilSec=0;}else throw ApiException.invalid("Unsupported candidate action.");updateEstimates(state);updateGraph(state);return new Trial(state,before,beforeRisk,beforeKnown,t.remainingDistanceM);}
    private ValidationResult constraints(State input,CandidateAction action,State trial,List<Impact> impacts){List<ConstraintViolation> violations=new ArrayList<>();Truck t=truck(trial,action.truckId());if(t.loadKg>t.capacityKg)violations.add(new ConstraintViolation("TRUCK_CAPACITY",List.of("truck:"+t.id),"Assigned truck load exceeds capacity.",true));for(Impact impact:impacts)if(impact.truckIds().contains(t.id)){// Operational conflicts constrain planning but waiting/rerouting may still be a safe improvement.
            violations.add(new ConstraintViolation(impact.code(),impact.resourceIds(),impact.message(),false));}
        boolean replaying=input.replaying;if(replaying)violations.add(new ConstraintViolation("REPLAY_LOCK",List.of("truck:"+t.id),"Reset the recorded replay before making operator interventions.",true));
        boolean valid=violations.stream().noneMatch(ConstraintViolation::blocking);return new ValidationResult(valid,fingerprint(input),List.copyOf(violations),SOURCE);}
    public Evaluation evaluate(State input,CandidateAction requested){Trial result=trial(input,requested);Truck t=truck(result.state,requested.truckId());State original=copy(input);updateEstimates(original);updateGraph(original);List<Impact> before=original.operations.predictedImpacts,after=result.state.operations.predictedImpacts;ValidationResult validation=constraints(input,requested,result.state,after);return new Evaluation(requested,fingerprint(input),result.beforeArrival,t.etaSec,result.remaining,t.etaSec-result.beforeArrival,result.beforeRisk,t.risk.score(),result.beforeKnown,t.etaKnown,original.operations.cascade,result.state.operations.cascade,List.copyOf(before),List.copyOf(after),validation,SOURCE);}
    public ValidationResult validate(State input,CandidateAction action){return evaluate(input,action).validation();}
    public CandidateAction optimize(List<Evaluation> evaluations,double clockSec){List<Evaluation> feasible=evaluations.stream().filter(e->e.validation().valid()).toList();if(feasible.isEmpty())return null;double maxTime=feasible.stream().mapToDouble(e->Math.max(1,e.afterArrivalSec()-clockSec)).max().orElse(1),maxDistance=feasible.stream().mapToDouble(e->Math.max(1,e.remainingDistanceM())).max().orElse(1),maxConflict=feasible.stream().mapToDouble(e->Math.max(1,e.afterImpacts().stream().mapToDouble(Impact::delaySec).sum())).max().orElse(1);Comparator<Evaluation> score=Comparator.comparingDouble(e->.65*Math.max(0,e.afterArrivalSec()-clockSec)/maxTime+.2*e.remainingDistanceM()/maxDistance+.15*e.afterImpacts().stream().mapToDouble(Impact::delaySec).sum()/maxConflict);return feasible.stream().min(score.thenComparing(e->e.candidate().action())).orElseThrow().candidate();}
    public RecommendationResult recommend(State input,String truckId){List<Evaluation> evaluations=candidates(input,truckId).candidates().stream().map(action->evaluate(input,action)).toList();CandidateAction selected=optimize(evaluations,input.clockSec);Explanation explanation=selected==null?new Explanation(API_VERSION,"No currently available incident-response action needs approval.",Map.of("truckId",truckId,"candidateCount",evaluations.size()),SOURCE):explain(evaluations.stream().filter(e->e.candidate().id().equals(selected.id())).findFirst().orElseThrow());return new RecommendationResult(context(input),truckId,evaluations,selected,explanation,SOURCE);}
    public Explanation explain(Evaluation evaluation){Map<String,Object> facts=new LinkedHashMap<>();facts.put("truckId",evaluation.candidate().truckId());facts.put("action",evaluation.candidate().action());facts.put("beforeArrivalSec",evaluation.beforeArrivalSec());facts.put("afterArrivalSec",evaluation.afterArrivalSec());facts.put("operationalEtaKnown",evaluation.afterEtaKnown());facts.put("travelDeltaSec",evaluation.travelDeltaSec());facts.put("beforePredictedImpacts",evaluation.beforeImpacts().size());facts.put("afterPredictedImpacts",evaluation.afterImpacts().size());facts.put("constraintViolations",evaluation.validation().violations());facts.put("stateFingerprint",evaluation.stateFingerprint());String eta=evaluation.afterEtaKnown()?String.format(Locale.ROOT,"a rule-estimated arrival of %.1f s",evaluation.afterArrivalSec()):String.format(Locale.ROOT,"an unknown operational arrival (conditional travel estimate %.1f s)",evaluation.afterArrivalSec());return new Explanation(API_VERSION,String.format(Locale.ROOT,"%s has %s (conditional change %+.1f s). %d configured operational conflicts remain forecast; road actions do not resolve every resource constraint. Execution requires an explicit operator approval and current-state validation.",evaluation.candidate().action(),eta,evaluation.travelDeltaSec(),evaluation.afterImpacts().size()),Collections.unmodifiableMap(facts),SOURCE);}
    public GraphSnapshotExporter.GraphSnapshot snapshot(State state){return exporter.snapshot(state);}
}
